mapper.select:
SELECT p.id, p.material_id AS materialId, m.code AS materialCode, m.name AS materialName, p.from_factory_id AS fromFactoryId, ff.name AS fromFactoryName, p.to_factory_id AS toFactoryId, tf.name AS toFactoryName, p.markup_type AS markupType, p.markup_value AS markupValue, p.status, p.remark, p.create_time AS createTime FROM org_transfer_price p LEFT JOIN base_material m ON m.id = p.material_id AND m.deleted = 0 LEFT JOIN org_factory ff ON ff.id = p.from_factory_id AND ff.deleted = 0 LEFT JOIN org_factory tf ON tf.id = p.to_factory_id AND tf.deleted = 0 WHERE p.deleted = 0
AND p.material_id = #{q.materialId}
AND p.from_factory_id = #{q.fromFactoryId}
AND p.to_factory_id = #{q.toFactoryId}
AND p.status = #{q.status}
ORDER BY p.id DESC

SELECT id, material_id, from_factory_id, to_factory_id,
       markup_type, markup_value, status, remark
FROM org_transfer_price
WHERE deleted = 0
  AND status = 1
  AND material_id = #{materialId}
  AND from_factory_id = #{fromFactoryId}
  AND to_factory_id = #{toFactoryId}
ORDER BY id DESC
LIMIT 1
